import string
import random

def generate_password(length=8):
    """Generate a random password with specified length."""
    characters = string.ascii_letters + string.digits + string.punctuation
    return ''.join(random.choice(characters) for _ in range(length))

# Get user input for password length
while True:
    try:
        length = int(input("Enter the desired length of the password (minimum 8): "))
        if length >= 8:
            break
        else:
            print("Password length must be at least 8 characters. Please try again.")
    except ValueError:
        print("Please enter a valid integer for password length.")

# Generate and display the password
password = generate_password(length)
print(f"Your password is: {password}")
```

This program will prompt the user for the desired length of the password, validate the input, and then generate a random password based on the user's input. The generated password will be displayed to the user.
